<?php
declare(strict_types=1);namespace Joomleague\Module\Personnel\Site\Helper;defined('_JEXEC')or die;use Joomla\CMS\Factory;use Joomla\Database\DatabaseInterface;use Joomla\Registry\Registry;use Joomleague\Component\Joomleague\Domain\Service\PersonnelReader;
final class PersonnelHelper{/** @return array<string,mixed> */public function getPersonnel(Registry$p):array{$id=(int)$p->get('project_id',0);if($id<1)return['error'=>'MOD_JOOMLEAGUE_PERSONNEL_NO_PROJECT'];$app=Factory::getApplication();$app->bootComponent('com_joomleague');$lang=Factory::getLanguage();$lang->load('com_joomleague',JPATH_SITE)||$lang->load('com_joomleague',JPATH_SITE.'/components/com_joomleague');try{$d=(new PersonnelReader(Factory::getContainer()->get(DatabaseInterface::class)))->forProject($id,$app->getIdentity()->getAuthorisedViewLevels());}catch (\Throwable $moduleFailure) { \Joomla\CMS\Log\Log::add('mod_joomleague_personnel failure: ' . get_debug_type($moduleFailure), \Joomla\CMS\Log\Log::WARNING, 'com_joomleague.modules');return['error'=>'MOD_JOOMLEAGUE_PERSONNEL_UNAVAILABLE'];}if(isset($d['error']))return['error'=>$d['error']==='project_required'?'MOD_JOOMLEAGUE_PERSONNEL_NO_PROJECT':'MOD_JOOMLEAGUE_PERSONNEL_UNAVAILABLE'];$group=(string)$p->get('group','all');if($group!=='all')foreach(array_keys($d['groups'])as$key)if($key!==$group&&!($group==='official'&&in_array($key,['adjudicator','competition_official','event_staff'],true)))$d['groups'][$key]=[];$limit=max(1,min(50,(int)$p->get('limit',10)));foreach($d['groups']as$key=>$rows)$d['groups'][$key]=array_slice(array_values($rows),0,$limit);foreach($d['groups']as$people)foreach($people as$person)$person->picture=\Joomleague\Component\Joomleague\Site\Service\MediaResolver::image('person',$person->picture);return$d;}}
